public String shortestPalindrome(String s) {
    String combined = s + "#" + reverse(s);
    int n = combined.length();
    int[] lps = new int[n];
    int len = 0;
    int i = 1;
    while (i < n) {
        if (combined.charAt(i) == combined.charAt(len)) {
            len++;
            lps[i] = len;
            i++;
        } else if (len != 0) {
            len = lps[len - 1];
        } else {
            lps[i] = 0;
            i++;
        }
    }
    int k = lps[n - 1];
    return reverse(s.substring(k)) + s;
}
